from pathlib import Path
import json

root = Path(__file__).resolve().parents[2]
path = root / 'evidence/01/notes.json'
n = json.loads(path.read_text(encoding='utf-8'))

read_pages = {
    'r2r': [7, 8], 'goat': [7, 8], 'hamt': [9, 10],
    'vlnbert': [7, 8], 'prevalent': [7, 8], 'kerm': [8],
    'airbert': [8], 'gavln': [8], 'overnav': [8], 'navillm': [8],
    'crossmodalmap': [8], 'rcm': [7, 8], 'regretful': [7, 8],
    'tacticalrewind': [7, 8], 'selfmonitoring': [7, 8, 9, 14, 15, 16, 17, 18]
}
for key, pages in read_pages.items():
    n[key]['pages'] = sorted(set(n[key]['pages']) | set(pages))

additions = {
    ('r2r', 'method'): 'Section 5.2, PDF p 7, trains per-step action cross entropy with the next shortest-path action from the current pose as target. Teacher forcing visits demonstration states; student forcing samples policy actions and relabels the visited states. The language and policy LSTMs each have 512 hidden units, word embeddings 256 dimensions, and action embeddings 32. Adam uses batch 100, dropout .5 and weight decay. Test decoding is greedy; the submitted test model uses both training and validation data, which must be separated from models used to report validation performance.',
    ('r2r', 'results'): 'Table 1, PDF p 7, gives student-forcing SR 38.6% on seen validation, 21.8% on unseen validation and 20.4% on test. Teacher forcing gives 19.6% unseen-validation SR, while the random baseline reaches 13.2% test SR and human navigators 86.4%. Figure 7/p 8 shows unseen performance plateauing while seen performance continues to improve. These measurements establish a concrete generalization gap under the original six-action interface.',
    ('goat', 'results'): 'Tables 1–2, PDF p 7, report R2R test SR 74.57/SPL 64.94 and REVERIE test RGS 38.32/RGSPL 26.70. Table 5 is a more controlled comparison: no adjustment gives unseen SR 75.27/SPL 64.69; both adjustment modules give 77.82/68.13. Table 7/p 8 shows text-attention plus vision-frequency weighting performing best at 68.13 SPL, versus 65.83 with attention for both. These experiments support the utility of the particular feature adjustments; neither improved benchmark scores nor object-keyword box plots identify a causal effect under the stated structural model.',
    ('goat', 'method'): 'Section 5.1, PDF p 6, specifies pretraining for up to 300k iterations with AdamW, batch 48 and learning rate 5e−5 on one V100, using MLM, SAP and contrastive pooling, plus object grounding for REVERIE/SOON. EnvEdit visual augmentation and external synthetic datasets are also used. The 74 keyword classes, 50 room classes and InfoNCE temperature 1 are part of the experimental configuration.',
    ('hamt', 'results'): 'Main Table 7, PDF p 9, compares models retrained on the R2R-Back task: unseen HAMT SR 57.2/SPL 53.1 versus RecBERT 41.1/37.7. This targeted return-to-start task supplies stronger memory evidence than a general R2R leaderboard difference. Table 6 gives R4R nDTW 50.3 versus 45.1 for reimplemented RecBERT. Table 8/p 10 reports CVDN goal progress 5.58m on test; it is not an SPL percentage.',
    ('vlnbert', 'results'): 'Table 3, PDF p 8, holds data and training strategy fixed for OSCAR-based architecture ablations: recurrent attention without the explicit matching refinement gives unseen SR 57.22/SPL 52.57, while the full model gives 58.71/53.41. Table 4 compares text-attention schedules under an 11GB budget, but batch size differs (6 versus 16); thus it is not a pure attention-only causal comparison. The full fixed-text variant uses 9.2GB at batch 16 in that setup.',
    ('prevalent', 'method'): 'Section 6.5, PDF p 8, clarifies that most downstream experiments use frozen pretrained features for computational efficiency. R2R additionally uses a two-stage adaptation that unfreezes cross-attention after feature-based training. These schedules should not be collapsed into a single claim that all pretrained parameters are always updated.',
    ('prevalent', 'results'): 'Table 5, PDF p 8, gives test SR/SPL 54/51 for two-stage R2R adaptation versus 52/49 using fixed features. Table 4 shows small and nonuniform increments from adding action pretraining on CVDN: for all dialog text and mixed supervision, goal progress is 3.15 versus 3.14 with multimodal MLM alone. The much larger comparison against ordinary BERT cannot be attributed solely to the action objective. HANNA Table 3/p 7 increases unseen SR from 47.45 to 52.91 while assistance requests also rise from 5.8 to 6.6.',
    ('kerm', 'results'): 'Table 6, PDF p 8, varies region granularity: REVERIE unseen SPL is 34.46 for one crop, 35.38 for five and 34.87 for nine. More retrieved regions are therefore not monotonically better. The selected qualitative attention example establishes relevance to an example, not factual correctness of every retrieved phrase.',
    ('airbert', 'results'): 'Table 9, PDF p 8, evaluates fine-tuning on one or six training houses, averaging five sampled house sets and excluding houses with fewer than 80 paths. To avoid leakage through an EnvDrop generator trained on all houses, candidate paths are random shortest routes. One-house unseen SR is 50.00 for AirBERT versus 22.43 for VLN-BERT. Here “one-shot” means one training environment and still involves training; it does not mean training-free navigation.',
    ('gavln', 'results'): 'Table 4, PDF p 8, tests additive sensor noise: SR falls from 60.96 to 59.11 with depth noise, 59.82 with pose noise and 58.29 with 5-degree rotation noise. The rotation decrease is 2.67 percentage points, so the nearby claim of a drop below two points is not true for every listed row. This finite Gaussian-noise test partially addresses sensor robustness but does not establish robustness to accumulated drift, bias or missing depth. The real-robot section presents examples in one room without a quantitative success denominator.',
    ('overnav', 'results'): 'Section 5.1, PDF p 8, explicitly explains that Type III memory contains the exact episode keywords in advance after a previous evaluation pass. Its advantage is therefore transductive repeated exposure, not the ordinary first-pass condition. The map visualization is a selected tour and does not quantify stale-memory behavior under changed objects.',
    ('navillm', 'results'): 'Table 5, PDF p 8, shows that extra pretraining does not improve every task: relative to multi-task training with a pretrained LLM, adding the pretraining stage increases R2R SPL 58→59 but lowers REVERIE SPL 36.63→35.68 and ScanQA exact match 23.3→22.1. Generalist data mixing has measurable tradeoffs.',
    ('crossmodalmap', 'results'): 'Section 4.2, PDF p 8, doubles the local map from 192 to 384 cells per side in the ground-truth-map experiment and reports gains of 5.6 SR points and 4.9 SPL points. This supports a concrete spatial-coverage bottleneck, although the oracle-map ablation does not establish the same gain for a learned hallucinated map.',
    ('rcm', 'results'): 'Table 2, PDF p 7, gives unseen SR 42.5 for RCM, 40.6 after removing intrinsic reward and 37.7 for supervised-only training. Figure 6/p 8 explicitly shows a success with matching reward 0.53 and a failure with reward 0.54 that stops 5.5m from the goal. This author-provided example directly shows that a high consistency reward does not certify correct final grounding.',
    ('regretful', 'results'): 'Table 3, PDF p 7, blocks rollback at inference: unseen SR falls from 48 to 46 while SPL rises from 37 to 41. This intervention supports the claimed recovery role and simultaneously exposes its movement cost. It is not evidence that rollback improves all metrics. Table 4 also shows synthetic-only training retaining good oracle visitation while correct stopping remains weaker than real-data training.',
    ('tacticalrewind', 'results'): 'Table 4, PDF p 8, reranks a fixed pool produced by 40 frontier expansions: all combined goal signals achieve unseen SR 64.03 versus 58.75 for mean log probability, 43.68 for speaker score alone and oracle 90.20. This is direct prior art for a learned visited-goal verifier using several global signals. Table 3/p 7 also finds raw-logit sums and log-probability sums close (56.66 versus 56.23 SR); it does not establish softmax normalization as the dominant source of error.',
    ('selfmonitoring', 'method'): 'Supplement PDF p 14 specifies 2176-dimensional view features (2048 ResNet plus 128 tiled angles), 512-dimensional recurrent states, a maximum of 80 instruction tokens, and a 592-to-1 progress projection combining hidden features with attention weights. Adam uses learning rate 1e−4 and batch 64; beam size is 15. The supplement describes physically logging and connecting searched trajectories for challenge submission.',
    ('selfmonitoring', 'results'): 'Main Table 2, PDF p 7, improves unseen greedy SR from 42 to 44 with the progress-training auxiliary, and then to 46 with progress-based inference. Supplement Table 3/p 14 reports augmented single-run test SR/SPL 43/32 for greedy decoding versus 48/35 for progress inference. Supplement pp 15–18 explicitly discuss failure despite apparently high completion, illustrating that progress estimates are imperfect. Text and figure captions were reviewed; the full image sequence was not independently visually adjudicated.',
}
for (key, field), text in additions.items():
    if text not in n[key][field]:
        n[key][field] += '\n\n' + text

n['rcm']['bottlenecks'][0]['evidence'] = 'Matching likelihood and SIL replay §3; Figure 6/PDF p 8 explicitly shows high intrinsic reward despite incorrect stopping'
n['rcm']['bottlenecks'][0]['confidence'] = 'high for the published counterexample; unknown frequency'
n['gavln']['bottlenecks'][0]['evidence'] = 'Eqs 1–5 and scatter-add implementation; Table 4/PDF p 8 partially tests additive Gaussian sensor noise'
n['overnav']['implementation'] = n['overnav']['implementation'].replace(
    'Supplementary prompts and architecture details remain distinct available material to audit.',
    'The locally supplied main paper was reviewed; a distinct supplementary prompt file was not included in this assignment inventory, and no claim of reviewing one is made.'
)
path.write_text(json.dumps(n, ensure_ascii=False, indent=2), encoding='utf-8')
print('Expanded original-result, ablation and internal-supplement coverage for 16 papers.')
